/** A typed request: its name, arguments and how to code both ends. */
sealed interface EngineSpec<A, R> {
    val name: String
    val args: A
    val argsSerializer: KSerializer<A>
    val resultSerializer: KSerializer<R>
}

/** A value view: `client.watch(Views.home())`, `client.query(Views.noteMeta(id))`. */
data class ViewSpec<A, V>(override val name: String, override val args: A, override val argsSerializer: KSerializer<A>, override val resultSerializer: KSerializer<V>) : EngineSpec<A, V>

/** A windowed list view: `client.watchList(ListViews.notesList(...))`. */
data class ListSpec<A, R>(override val name: String, override val args: A, override val argsSerializer: KSerializer<A>, override val resultSerializer: KSerializer<R>) : EngineSpec<A, R>

/** A command (a write): `client.command(Commands.noteStar(ids, true))`. */
data class CommandSpec<A, R>(override val name: String, override val args: A, override val argsSerializer: KSerializer<A>, override val resultSerializer: KSerializer<R>) : EngineSpec<A, R>

/** An editor command (the note page): `client.editor(EditorCommands.notePrepare(id))`. */
data class EditorSpec<A, R>(override val name: String, override val args: A, override val argsSerializer: KSerializer<A>, override val resultSerializer: KSerializer<R>) : EngineSpec<A, R>

