    fun taskToggle(blockId: String): EditorSpec<TaskToggleArgs, OkResult> = EditorSpec("task.toggle", TaskToggleArgs(blockId = blockId), TaskToggleArgs.serializer(), OkResult.serializer())
    fun threadOpen(threadId: String): EditorSpec<ThreadOpenArgs, OkResult> = EditorSpec("thread.open", ThreadOpenArgs(threadId = threadId), ThreadOpenArgs.serializer(), OkResult.serializer())
    fun find(query: String, index: Long? = null): EditorSpec<FindArgs, FindResult> = EditorSpec("find", FindArgs(query = query, index = index), FindArgs.serializer(), FindResult.serializer())
    fun findClear(): EditorSpec<EmptyArgs, OkResult> = EditorSpec("find.clear", EmptyArgs, EmptyArgs.serializer(), OkResult.serializer())
}

