/** An event from the engine with its typed data. Unknown names (a newer engine) arrive as [Unknown]. */
sealed interface EngineEvent {
    val name: String

    data class EngineReady(val data: com.folevi.engine.generated.EngineReadyEvent) : EngineEvent {
        override val name: String get() = "engine.ready"
    }

    data class GateChanged(val data: com.folevi.engine.generated.GateChangedEvent) : EngineEvent {
        override val name: String get() = "gate.changed"
    }

    data class SyncStatus(val data: com.folevi.engine.generated.SyncStatusValue) : EngineEvent {
        override val name: String get() = "sync.status"
    }

    data class PlaceChanged(val data: com.folevi.engine.generated.PlaceChangedEvent) : EngineEvent {
        override val name: String get() = "place.changed"
    }

    data class Toast(val data: com.folevi.engine.generated.ToastEvent) : EngineEvent {
        override val name: String get() = "toast"
    }

    data class NavigateRequest(val data: com.folevi.engine.generated.NavigateRequestEvent) : EngineEvent {
        override val name: String get() = "navigate.request"
    }

    data class PanesChange(val data: com.folevi.engine.generated.PanesChangeEvent) : EngineEvent {
        override val name: String get() = "panes.change"
    }

    data class NoteReady(val data: com.folevi.engine.generated.NoteReadyEvent) : EngineEvent {
        override val name: String get() = "note.ready"
    }

    data class NoteMeta(val data: com.folevi.engine.generated.NoteMeta) : EngineEvent {
        override val name: String get() = "note.meta"
    }

    data class EditorState(val data: com.folevi.engine.generated.EditorStateEvent) : EngineEvent {
        override val name: String get() = "editor.state"
    }

    data class EditorPanel(val data: com.folevi.engine.generated.EditorPanelEvent) : EngineEvent {
        override val name: String get() = "editor.panel"
    }

    data class MemoryRelieved(val data: com.folevi.engine.generated.MemoryRelievedEvent) : EngineEvent {
        override val name: String get() = "memory.relieved"
    }

    data class NoteTools(val data: com.folevi.engine.generated.NoteToolsEvent) : EngineEvent {
        override val name: String get() = "note.tools"
    }

    data class Unknown(override val name: String, val data: JsonElement) : EngineEvent

    companion object {
        /** Decodes the `data` of an event named `name`. */
        fun decode(json: Json, name: String, data: JsonElement?): EngineEvent {
            val d = data ?: JsonNull
            return when (name) {
                "engine.ready" -> EngineReady(json.decodeFromJsonElement(com.folevi.engine.generated.EngineReadyEvent.serializer(), d))
                "gate.changed" -> GateChanged(json.decodeFromJsonElement(com.folevi.engine.generated.GateChangedEvent.serializer(), d))
                "sync.status" -> SyncStatus(json.decodeFromJsonElement(com.folevi.engine.generated.SyncStatusValue.serializer(), d))
                "place.changed" -> PlaceChanged(json.decodeFromJsonElement(com.folevi.engine.generated.PlaceChangedEvent.serializer(), d))
                "toast" -> Toast(json.decodeFromJsonElement(com.folevi.engine.generated.ToastEvent.serializer(), d))
                "navigate.request" -> NavigateRequest(json.decodeFromJsonElement(com.folevi.engine.generated.NavigateRequestEvent.serializer(), d))
                "panes.change" -> PanesChange(json.decodeFromJsonElement(com.folevi.engine.generated.PanesChangeEvent.serializer(), d))
                "note.ready" -> NoteReady(json.decodeFromJsonElement(com.folevi.engine.generated.NoteReadyEvent.serializer(), d))
                "note.meta" -> NoteMeta(json.decodeFromJsonElement(com.folevi.engine.generated.NoteMeta.serializer(), d))
                "editor.state" -> EditorState(json.decodeFromJsonElement(com.folevi.engine.generated.EditorStateEvent.serializer(), d))
                "editor.panel" -> EditorPanel(json.decodeFromJsonElement(com.folevi.engine.generated.EditorPanelEvent.serializer(), d))
                "memory.relieved" -> MemoryRelieved(json.decodeFromJsonElement(com.folevi.engine.generated.MemoryRelievedEvent.serializer(), d))
                "note.tools" -> NoteTools(json.decodeFromJsonElement(com.folevi.engine.generated.NoteToolsEvent.serializer(), d))
                else -> Unknown(name, d)
            }
        }
    }
}
